// Extracts a path from the A* grid search result by walking parent pointers. Similar to ExtractPathFromResult but used by the grid-based A* (PathTypeFunc_01). Returns the number of waypoints (max 77).
static int32_t DRLGPATH_ExtractPathFromResult2(D2PathTypeArg * pPathTypeArg, D2DrlgPathNodeStrc * pCurNode) {
    int iVar1;
    int nDeltaY;
    D2PathExtractFrameStrc sFrame;
    sFrame.pWaypointDst = pPathTypeArg->pDynamicPath->PathPoints;
    int nWaypointCount = 0;
    int nPrevDeltaX = -2;
    sFrame.nPrevDeltaY = -2;
    if (!pCurNode) {
      return 0;
    }

    sFrame.pWritePtr = sFrame.aWaypoints + 0x4d;
    do {
      if (nWaypointCount >= 0x4e) {
        break;
      }

      sFrame.pParentNode = (void**)pCurNode->pParent;
      if ((D2DrlgPathNodeStrc*)sFrame.pParentNode) {
        iVar1 = (uint32_t)(uint16_t)pCurNode->nX - (uint32_t)(uint16_t)((D2DrlgPathNodeStrc*)sFrame.pParentNode)->nX;
        nDeltaY = (uint32_t)(uint16_t)pCurNode->nY - (uint32_t)(uint16_t)((D2DrlgPathNodeStrc*)sFrame.pParentNode)->nY;
        if (iVar1 != nPrevDeltaX || nDeltaY != sFrame.nPrevDeltaY) {
          *sFrame.pWritePtr = *(uint32_t*)pCurNode;
          nWaypointCount++;
          sFrame.pWritePtr--;
          nPrevDeltaX = iVar1;
          sFrame.nPrevDeltaY = nDeltaY;
        }
      }

      pCurNode = (D2DrlgPathNodeStrc*)sFrame.pParentNode;
    } while ((D2DrlgPathNodeStrc*)sFrame.pParentNode);

    if (nWaypointCount >= 0x1 && nWaypointCount <= 0x4d) {
      memcpy(sFrame.pWaypointDst, (void*)((intptr_t)&sFrame + (nWaypointCount * -4 + 0x138)), nWaypointCount * 4);
      return nWaypointCount;
    }

    return 0;
}

// Already has a meaningful description.
static int32_t DRLGPATH_CheckSurroundingCollisions(D2PathTypeArg * pPathTypeArg) {
    eCollisionFlags eCollisionFlag;
    if (!pPathTypeArg->pDynamicPath->pTargetUnit) {
      return 1;
    }

    uint32_t nX = (uint32_t)pPathTypeArg->tTargetCoord.nX;
    D2RoomStrc* pRoom = pPathTypeArg->pRoom;
    int32_t nType = pPathTypeArg->nCollisionPattern;
    int32_t iVar2 = pPathTypeArg->nCollisionMask;
    uint32_t nY = (uint32_t)pPathTypeArg->tTargetCoord.nY;
    int32_t iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX - 2, nY - 2, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    int nYPlus2 = nY + 2;
    iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX - 2, nYPlus2, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX + 2, nY - 2, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX + 2, nYPlus2, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX - 2, nY, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX, nY - 2, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    iVar1 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX + 2, nY, nType, iVar2);
    if (!iVar1) {
      return 1;
    }

    iVar2 = Collision::CheckCollision_BlockPlayer_Type(pRoom, nX, nYPlus2, nType, iVar2);
    return (uint32_t)!iVar2;
}

// Fallback A* used when the greedy directional search does not reach the destination and the squared distance is under 0x145. The whole search state is ONE 0x32EC-byte frame object whose base is handed to every helper, which then reach the rest by byte offset: DRLGPATH_AllocPathNode takes the pool count at base+0x2FC4 and node n at base+0x404+n*0x38; DRLGPATH_InsertNodeSorted and PopBestNodeFromOpenList use the closed buckets at base+0x200 and the sorted head at base+0x400; DRLGPATH_PropagateNodeCosts uses the queue at base+0x2FC8 and its count at base+0x32E8. Split into separate locals the helpers wrote nodes over unrelated stack and read the list head out of garbage, which faulted on every player move long enough to need the A* fallback and on NPC paths.
int32_t __fastcall PATH_FindPathAStarLocalPool(D2PathTypeArg * pPathTypeArg) {
    int32_t nExtractResult;
    D2DrlgPathSearchCtxStrc abyOpenList;
    int32_t nPathLength;
    short int nHeuristic;
    int32_t iVar2 = DRLGPATH_CheckSurroundingCollisions(pPathTypeArg);
    if (!iVar2) {
      return 0;
    }

    D2DrlgPathNodeStrc* pClosestNode = 0;
    abyOpenList.nPoolCount = 0;
    abyOpenList.pSortedHead = 0;
    abyOpenList.nPropagateCount = 0;
#if D2_ARCH_X86
    memset(&abyOpenList, 0, 0x200);
#elif D2_ARCH_X64
    memset(&abyOpenList, 0, sizeof(abyOpenList));
#endif
    memset(abyOpenList.apClosedBuckets, 0, sizeof(abyOpenList.apClosedBuckets));
    D2PathPointStrc DVar1 = pPathTypeArg->tStartCoord;
    D2PathPointStrc nStartPacked = pPathTypeArg->tTargetCoord;
    if (abyOpenList.nPoolCount != 200) {
      pClosestNode = abyOpenList.aNodePool + abyOpenList.nPoolCount;
      abyOpenList.nPoolCount++;
      memset(pClosestNode, 0, sizeof(D2DrlgPathNodeStrc));
    }

    int32_t nDeltaX = (uint16_t)(uint32_t)d2_bits_of(DVar1) - (uint16_t)(uint32_t)d2_bits_of(nStartPacked);
    pClosestNode->nGCost = 0;
    if (nDeltaX < 0) {
      nDeltaX = -nDeltaX;
    }

    int32_t nDeltaY = ((uint32_t)d2_bits_of(DVar1) >> 0x10) - ((uint32_t)d2_bits_of(nStartPacked) >> 0x10);
    if (nDeltaY < 0) {
      nDeltaY = -nDeltaY;
    }
    if (!(nDeltaX < nDeltaY)) {
      nHeuristic = (short int)nDeltaY + (short int)nDeltaX * 2;
    } else {
      nHeuristic = (short int)nDeltaX + (short int)nDeltaY * 2;
    }

    pClosestNode->nX = DVar1.nX;
    pClosestNode->nY = DVar1.nY;
    pClosestNode->nHCost = nHeuristic;
    pClosestNode->nFCost = nHeuristic;
    DRLGPATH_InsertNodeSorted(&abyOpenList, pClosestNode);
    pClosestNode = 0;
    D2DrlgPathNodeStrc* pBestNodeOut = (D2DrlgPathNodeStrc*)DRLGPATH_PopBestNodeFromOpenList(&abyOpenList);
    if (pBestNodeOut) {
      BOOL bExpandedAny;
      do {
        if (!pClosestNode || pBestNodeOut->nHCost < pClosestNode->nHCost || pBestNodeOut->nHCost == pClosestNode->nHCost && (int)pBestNodeOut->nGCost > pClosestNode->nGCost + 5) {
          pClosestNode = pBestNodeOut;
        }
        if (!pBestNodeOut->nHCost) {
          break;
        }

        bExpandedAny = DRLGPATH_ExpandAllNeighbors((uint16_t*)pBestNodeOut, &abyOpenList, (uint32_t)d2_bits_of(nStartPacked), pPathTypeArg);
        if (!bExpandedAny) {
          break;
        }

        pBestNodeOut = (D2DrlgPathNodeStrc*)DRLGPATH_PopBestNodeFromOpenList(&abyOpenList);
      } while (pBestNodeOut);

      if (pClosestNode) {
        nExtractResult = DRLGPATH_ExtractPathFromResult2(pPathTypeArg, pClosestNode);
        return nExtractResult;
      }
    }

    return 0;
}

// Computes the squared Euclidean distance between two packed (X|Y) coordinates. Returns dx*dx + dy*dy. No callers found - likely referenced via function pointer table or dead code.
int32_t __stdcall DRLGPATH_GetSquaredDistancePacked(uint32_t nPackedA, uint32_t nPackedB) {
    int nDeltaX = (uint16_t)nPackedA - (uint16_t)nPackedB;
    int nDeltaY = (nPackedA >> 0x10) - (nPackedB >> 0x10);
    return nDeltaY * nDeltaY + nDeltaX * nDeltaX;
}

// Builds a list of coordinate points along a Bresenham line from source to destination. Stores packed (X,Y) coordinates in the output buffer and returns the point count. Sets the initial direction in *pnInitDir. Used by PathTypeFunc_15.
int32_t __stdcall DRLGPATH_BuildBresenhamPointList(uint32_t nSrcPacked, uint32_t nDstPacked, int32_t nMaxSteps, uint32_t * pnInitDir, D2PathPointStrc * pwPointsBuf) {
    int32_t nStepY;
    uint32_t nCurX;
    int nMaxStepsM1 = nMaxSteps - 1;
    *pnInitDir = 0;
    int32_t nDeltaX = (uint16_t)nDstPacked - (uint16_t)nSrcPacked;
    uint32_t nSrcY = nSrcPacked >> 0x10;
    uint32_t nDeltaY = (nDstPacked >> 0x10) - nSrcY;
    int nPointCount = 0;
    if (nDeltaX < 0) {
      nDeltaX = -nDeltaX;
      nDstPacked = -1;
    } else {
      nDstPacked = 1;
    }
    if ((int)nDeltaY < 0) {
      nDeltaY = -nDeltaY;
      nStepY = -1;
    } else {
      nStepY = 1;
    }
    if (!nDeltaX) {
      if ((int)nDeltaY <= 0) {
        pwPointsBuf[nPointCount].nX = 0;
        return nPointCount;
      }

      *pnInitDir = nStepY > 0 ? 0x2 : 0;
      if ((int)nDeltaY <= nMaxStepsM1) {
        do {
          nSrcY += nStepY;
          pwPointsBuf[nPointCount].nX = (uint16_t)nSrcPacked;
          pwPointsBuf[nPointCount].nY = (uint16_t)nSrcY;
          nPointCount++;
          nDeltaY--;
        } while (nDeltaY);

        pwPointsBuf[nPointCount].nX = 0;
        return nPointCount;
      }
    } else {
      uint32_t nCurY;
      nCurX = nSrcPacked & 0xffff;
      nCurY = (uint32_t)*(uint16_t*)((char*)&nSrcPacked + 2);
      if (!nDeltaY) {
        *pnInitDir = (int)nDstPacked <= 0 ? 0x3U : 0x1U;
        if (nDeltaX <= nMaxStepsM1) {
          do {
            nCurX += nDstPacked;
            pwPointsBuf[nPointCount].nX = (uint16_t)nCurX;
            pwPointsBuf[nPointCount].nY = *(uint16_t*)((char*)&nSrcPacked + 2);
            nPointCount++;
            nDeltaX--;
          } while (nDeltaX);

          pwPointsBuf[nPointCount].nX = 0;
          return nPointCount;
        }
      } else if (!(nDeltaX < (int)nDeltaY)) {
        *pnInitDir = (int)nDstPacked <= 0 ? 0x3U : 0x1U;
        if (nDeltaX <= nMaxStepsM1) {
          nSrcPacked = 0;
          nMaxSteps = nDeltaX;
          do {
            nCurX += nDstPacked;
            nSrcPacked += nDeltaY;
            if ((int)nSrcPacked >= nDeltaX) {
              nSrcPacked -= nDeltaX;
              nCurY += nStepY;
            }

            pwPointsBuf[nPointCount].nX = (uint16_t)nCurX;
            pwPointsBuf[nPointCount].nY = (uint16_t)nCurY;
            nPointCount++;
            nMaxSteps--;
          } while (nMaxSteps);

          pwPointsBuf[nPointCount].nX = 0;
          return nPointCount;
        }
      } else {
        *pnInitDir = nStepY > 0 ? 0x2 : 0;
        if ((int)nDeltaY <= nMaxStepsM1) {
          nMaxSteps = 0;
          nSrcPacked = nDeltaY;
          do {
            nCurY += nStepY;
            nMaxSteps += nDeltaX;
            if (nMaxSteps >= (int)nDeltaY) {
              nMaxSteps -= nDeltaY;
              nCurX += nDstPacked;
            }

            pwPointsBuf[nPointCount].nX = (uint16_t)nCurX;
            pwPointsBuf[nPointCount].nY = (uint16_t)nCurY;
            nPointCount++;
            nSrcPacked--;
          } while (nSrcPacked);

          pwPointsBuf[nPointCount].nX = 0;
          return nPointCount;
        }
      }
    }

    pwPointsBuf->nX = 0;
    return 0;
}

// Computes a direction lookup value from two packed coordinates using a table at 0x6F1E28. The index is computed as (dy*3 - srcX + dstX), suggesting a 3-state direction encoding. No callers found - likely used via function pointer.
uint32_t __stdcall DRLGPATH_GetDirectionLookupFromPacked(uint32_t nSrcPacked, uint32_t nDstPacked) {
    return gaPathDirectionLookupTable[((nDstPacked >> 0x10) - (nSrcPacked >> 0x10)) * 3 - (uint16_t)nSrcPacked + (uint16_t)nDstPacked];
}

